create or replace function public.layer2_run_batch_create(p_profile_id uuid,p_trigger_type text,p_requested_by uuid,p_items jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog,pipeline as $$ declare v_profile pipeline.layer2_source_profiles%rowtype; v_policy pipeline.layer2_execution_policies%rowtype; v_batch uuid:=gen_random_uuid(); v_count integer; begin if p_trigger_type not in ('manual','schedule','trial','resume') then raise exception 'invalid trigger_type'; end if; if jsonb_typeof(p_items)<>'array' then raise exception 'items must be array'; end if; v_count:=jsonb_array_length(p_items); if v_count<1 or v_count>100 then raise exception 'batch item count must be 1..100'; end if; select * into v_profile from pipeline.layer2_source_profiles where id=p_profile_id; if not found then raise exception 'profile not found'; end if; if not v_profile.enabled or v_profile.paused then raise exception 'profile not executable'; end if; if v_profile.current_version_id is null then raise exception 'profile has no current version'; end if; select * into v_policy from pipeline.layer2_execution_policies where profile_id=p_profile_id; if not found then raise exception 'execution policy missing'; end if; insert into pipeline.layer2_run_batches(id,profile_id,profile_version_id,trigger_type,status,requested_by,policy_snapshot,target_count) values(v_batch,p_profile_id,v_profile.current_version_id,p_trigger_type,'queued',p_requested_by,jsonb_build_object('schedule_mode',v_policy.schedule_mode,'batch_size',v_policy.batch_size,'routing_strategy',v_policy.routing_strategy,'max_paid_attempts_per_entity',v_policy.max_paid_attempts_per_entity,'max_vendor_units_per_entity',v_policy.max_vendor_units_per_entity,'max_cost_usd_per_entity',v_policy.max_cost_usd_per_entity,'auto_handoff_layer3',v_policy.auto_handoff_layer3,'stop_on_identity_mismatch',v_policy.stop_on_identity_mismatch),v_count); insert into pipeline.layer2_run_items(id,batch_id,entity_type,entity_id,source_url,status,selected_provider_id) select gen_random_uuid(),v_batch,lower(x->>'entity_type'),(x->>'entity_id')::uuid,x->>'source_url','queued',nullif(x->>'provider_id','')::uuid from jsonb_array_elements(p_items) x; if exists(select 1 from pipeline.layer2_run_items where batch_id=v_batch and (entity_type not in ('course','scholarship') or entity_id is null or nullif(source_url,'') is null)) then raise exception 'each item requires valid entity_type, entity_id and source_url'; end if; if exists(select 1 from pipeline.layer2_run_items i left join pipeline.layer2_acquisition_providers p on p.id=i.selected_provider_id where i.batch_id=v_batch and i.selected_provider_id is not null and (p.id is null or not p.enabled)) then raise exception 'selected provider invalid or disabled'; end if; return v_batch; end $$; revoke all on function public.layer2_run_batch_create(uuid,text,uuid,jsonb) from public,anon,authenticated; grant execute on function public.layer2_run_batch_create(uuid,text,uuid,jsonb) to service_role;
create or replace function public.layer2_run_batch_reconcile(p_batch_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,pipeline as $$ declare v_total int; v_processed int; v_resolved int; v_l3 int; v_blocked int; v_units numeric; v_cost numeric; v_status text; begin if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; select count(*),count(*) filter(where status not in ('queued','discovering','acquiring','extracting')),count(*) filter(where status='resolved_l2'),count(*) filter(where status='layer3_required'),count(*) filter(where status='blocked'),coalesce(sum(vendor_units),0),coalesce(sum(vendor_cost_usd),0) into v_total,v_processed,v_resolved,v_l3,v_blocked,v_units,v_cost from pipeline.layer2_run_items where batch_id=p_batch_id; v_status:=case when v_total=0 then 'failed' when v_processed<v_total then 'running' when v_blocked=v_total then 'failed' when v_blocked>0 or v_l3>0 then 'partial' else 'completed' end; update pipeline.layer2_run_batches set status=v_status,processed_count=v_processed,resolved_l2_count=v_resolved,escalated_l3_count=v_l3,blocked_count=v_blocked,vendor_units=v_units,vendor_cost_usd=v_cost,started_at=coalesce(started_at,case when v_status<>'queued' then now() end),completed_at=case when v_processed=v_total then coalesce(completed_at,now()) else null end where id=p_batch_id; return public.layer2_run_batch_summary(p_batch_id); end $$; revoke all on function public.layer2_run_batch_reconcile(uuid) from public,anon,authenticated; grant execute on function public.layer2_run_batch_reconcile(uuid) to service_role;
